DECLARE @Json NVARCHAR(MAX) = N'{
  "Name": "Adjustable Race",
  "Vendor": {"Name": "Contoso", "City": "Redmond"}
}';

SELECT JSON_VALUE(@Json, '$.Name') AS ProductName,
       JSON_VALUE(@Json, '$.Vendor.City') AS VendorCity;

DECLARE @ProductJson NVARCHAR(MAX) =
  (SELECT TOP 1 ProductID, Name, ListPrice
   FROM Production.Product ORDER BY ProductID
   FOR JSON PATH, WITHOUT_ARRAY_WRAPPER);

SELECT JSON_VALUE(@ProductJson, '$.Name') AS ProductName,
       JSON_VALUE(@ProductJson, '$.ListPrice') AS ListPriceAsText;
